// Résumé ultra-lisible toutes les 10 s PAR BMS. Aucun MQTT.
const d=msg.payload || {};
const address=String(d.address || "").toUpperCase();
if (!address || d.validation!=="provisional_compare_with_BatMON") return null;
const fields=["voltage_v","current_a","power_w","soc_pct","cell_count","cell_delta_mv"];
if (fields.some(k=>!Number.isFinite(Number(d[k])))) return null;
const now=Date.now(),key="last_summary:"+address;
const last=context.get(key) || 0;
if (now-last<10000) return null;
context.set(key,now);
function number(v,dec){return Number(v).toFixed(dec);}
const temps=[["T1",d.temp1_c],["T2",d.temp2_c],["MOS",d.mos_temp_c]]
  .filter(x=>Number.isFinite(Number(x[1])))
  .map(x=>x[0]+" "+number(x[1],1)+"°C");
const shortAddress=address.split(":").slice(-2).join(":");
const amperes=Number(d.current_a);
const watts=Number(d.power_w);
const summary=[
  "BMS "+shortAddress,
  number(d.voltage_v,2)+" V",
  (amperes>0?"+":"")+number(amperes,2)+" A",
  (watts>0?"+":"")+number(watts,0)+" W",
  "SOC "+number(d.soc_pct,0)+"%",
  number(d.cell_count,0)+" cellules",
  "Δ "+number(d.cell_delta_mv,0)+" mV",
  ...temps,
  d.format+" (à vérifier)"
].join(" | ");
node.status({fill:"green",shape:"dot",text:summary.slice(0,82)});
msg.topic="jk/"+address+"/resume";
msg.payload=summary;
return msg;

